{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C11"],
      "claim": "Pentosan polysulfate sodium had oral bioavailability of 0.5–1% in healthy subjects after daily 400 mg oral dosing, well below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Zanamivir absolute oral bioavailability was 2% (range 1–5%) in volunteers receiving 500 mg orally vs 50 mg IV, well below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "Acamprosate absolute oral bioavailability was 11 ± 1% in healthy male volunteers after 666 mg oral tablets vs IV, below the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All supplied quantitative oral bioavailability records are below 20% (0.5–1%, 2%, 4%, 4–11.6%, 11%), and qualitative records consistently describe low or poor bioavailability; therefore the prediction is low.",
  "evidence_gaps": [
    "One acetylcysteine record (C04) reports ~80% oral bioavailability, conflicting with multiple NAC numeric records; discounted as inconsistent.",
    "Several records are qualitative rather than numeric, but the quantitative absolute records are sufficient to establish the low direction."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

